def is_valid_parentheses(s: str) -> bool:
    """Check bracket validity using a stack, O(n) time."""
    stack: list[str] = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in pairs.values():
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
```
Stack-based single pass with early exit on mismatch.

